-- ============================================================================
-- FUNCIONES ÚTILES PARA CIVIX
-- ============================================================================

-- Función: Obtener sección por coordenadas GPS
CREATE OR REPLACE FUNCTION get_section_by_location(lat DOUBLE PRECISION, lng DOUBLE PRECISION)
RETURNS TABLE (
    section_id UUID,
    section_number INTEGER,
    district_number INTEGER
) AS $$
BEGIN
    RETURN QUERY
    SELECT es.id, es.section_number, ed.district_number
    FROM electoral_sections es
    JOIN electoral_districts ed ON es.district_id = ed.id
    WHERE ST_Contains(es.geom, ST_SetSRID(ST_MakePoint(lng, lat), 4326))
    LIMIT 1;
END;
$$ LANGUAGE plpgsql;

-- Función: Obtener secciones cercanas (radio en metros)
CREATE OR REPLACE FUNCTION get_nearby_sections(lat DOUBLE PRECISION, lng DOUBLE PRECISION, radius_meters INTEGER DEFAULT 1000)
RETURNS TABLE (
    section_id UUID,
    section_number INTEGER,
    distance_meters DOUBLE PRECISION
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        es.id,
        es.section_number,
        ST_Distance(
            es.geom::geography, 
            ST_SetSRID(ST_MakePoint(lng, lat), 4326)::geography
        ) as distance
    FROM electoral_sections es
    WHERE ST_DWithin(
        es.geom::geography,
        ST_SetSRID(ST_MakePoint(lng, lat), 4326)::geography,
        radius_meters
    )
    ORDER BY distance;
END;
$$ LANGUAGE plpgsql;

